function compute(inputs){
  const raw = inputs.probs.slice(0, parseInt(inputs.n));
  const sumRaw = raw.reduce((a,b)=>a+b,0);
  let p;
  if (sumRaw === 0) {
    p = raw.map(()=> 1/raw.length);
  } else {
    p = raw.map(v => v/sumRaw);
  }
  const contributions = p.map(pi => pi === 0 ? 0 : -pi * Math.log2(pi));
  const H = contributions.reduce((a,b)=>a+b,0);
  const table = {
    columns: ["Outcome", "p_i", "-log2(p_i)", "Contribution"],
    rows: p.map((pi, i) => [
      i+1,
      pi,
      pi === 0 ? "—" : -Math.log2(pi),
      contributions[i]
    ])
  };
  const insight = `Entropy H = ${H.toFixed(3)} bits. ` +
    (H === 0 ? "Certainty: no uncertainty." :
     `Maximum possible for ${p.length} outcomes is ${Math.log2(p.length).toFixed(3)} bits.`) +
    (sumRaw === 0 ? " (All probabilities zero; using uniform distribution.)" : "");
  return {
    H: H,
    p: p,
    contributions: contributions,
    table: table,
    insight: insight,
    warning: sumRaw === 0 ? "All probabilities zero; auto-normalized to uniform." : null
  };
}
